#!/bin/bash

# This file is documentation for how to get started with Muse-Spark-Open-816B-A42B.

# This file runs Step 2 on a TPU v7x slice on a daily basis: logit check, pre-training, fine-tuning and decoding.
# The training steps below do not fit on 16 chips (tpu7x-32). They compile within HBM on 32 chips (tpu7x-64)
# and have been run on a 64-chip tpu7x-128 slice.
# Step 1 (1_test_muse_spark_816b_a42b.sh) converts the HuggingFace checkpoint.

# The golden logits can be generated by:
# python3 -m tests.assets.logits_generation.generate_hf_golden_logits --model-id=meta-models/Muse-Spark-Open-816B-A42B --output-path=golden_data_muse-spark-816b-a42b.jsonl --prompts='I love to' --hf-model-path=$local_bf16_path --trust-remote-code=False --hf-load-dtype=bfloat16

set -ex

# Ensure JetStream and dependencies are installed for inference.decode
if ! python3 -c "import jetstream" &>/dev/null; then
  python3 -m src.dependencies.scripts.install_pre_train_extra_deps --with-tf
fi

export LIBTPU_INIT_ARGS="--xla_tpu_scoped_vmem_limit_kib=65536"
export MODEL_NAME='muse-spark-816b-a42b'
export TOKENIZER_PATH='meta-models/Muse-Spark-Open-816B-A42B'

# Installing torch for forward_pass_logit_checker.py
python3 -m pip install torch --index-url https://download.pytorch.org/whl/cpu

if [ -z "${BASE_OUTPUT_PATH}" ]; then
  # Non-Googlers please remember to point `BASE_OUTPUT_PATH` to GCS buckets that you own, this script uses internal buckets for testing.
  # this bucket will store all the files generated by MaxText during a run
  export BASE_OUTPUT_PATH=gs://runner-maxtext-logs/$(date +%Y-%m-%d-%H-%M)
  echo "BASE_OUTPUT_PATH is not set"
fi
BASE_OUTPUT_PATH=${BASE_OUTPUT_PATH%/}
echo using BASE_OUTPUT_PATH = ${BASE_OUTPUT_PATH}

# Use hard-coded golden checkpoints rather than checkpoints generated by Step 1, which is not in the daily test.
SCANNED_CKPT_PATH=${SCANNED_CKPT_PATH:-gs://maxtext-model-checkpoints/${MODEL_NAME}/scanned/0/items}
UNSCANNED_CKPT_PATH=${UNSCANNED_CKPT_PATH:-gs://maxtext-model-checkpoints/${MODEL_NAME}/unscanned/0/items}
# Non-Googlers please remember to point `DATASET_PATH` to the GCS bucket where you have your training data
export DATASET_PATH=${DATASET_PATH:-gs://maxtext-dataset}

# Test whether the forward pass logits match the golden logits
# default golden_logits_path=/deps/tests/assets/golden_logits/golden_data_{MODEL_NAME}.jsonl, copied from gs://maxtext-test-assets/golden_data_${MODEL_NAME}.jsonl
GOLDEN_LOGITS_DISK_LOCATION="/deps/tests/assets/golden_logits/golden_data_${MODEL_NAME}.jsonl"
if [ ! -f "${GOLDEN_LOGITS_DISK_LOCATION}" ]; then
  GOLDEN_LOGITS_PATH="gs://maxtext-test-assets/golden_data_${MODEL_NAME}.jsonl"
  GOLDEN_LOGITS_DISK_LOCATION=/tmp/golden_data.jsonl
  gcloud storage cp ${GOLDEN_LOGITS_PATH} ${GOLDEN_LOGITS_DISK_LOCATION}
fi

python3 -m tests.utils.forward_pass_logit_checker ${MAXTEXT_CONFIGS_DIR:-${MAXTEXT_REPO_ROOT:-$PWD}/src/maxtext/configs}/base.yml base_output_directory=${BASE_OUTPUT_PATH} run_name=forward_logits_check load_parameters_path=${SCANNED_CKPT_PATH} scan_layers=true attention=dot_product per_device_batch_size=1 model_name=${MODEL_NAME} max_prefill_predict_length=4 max_target_length=4 async_checkpointing=false ici_fsdp_parallelism=-1 ici_tensor_parallelism=4 weight_dtype=float32 dtype=float32 activations_in_float32=true matmul_precision=highest float32_logits=true float32_qk_product=true --golden_logits_path=${GOLDEN_LOGITS_DISK_LOCATION} --atol=1.5 --rtol=1.5 --max_kl_div=0.2 --skip_first_token

# Run pre-training
# AdamW state does not fit for this model on the daily slice; use SGD like the DeepSeek 671B/284B daily tests.
python3 -m maxtext.trainers.pre_train.train ${MAXTEXT_CONFIGS_DIR:-${MAXTEXT_REPO_ROOT:-$PWD}/src/maxtext/configs}/base.yml base_output_directory=${BASE_OUTPUT_PATH} run_name=muse_spark_pre_training model_name=${MODEL_NAME} tokenizer_type=huggingface tokenizer_path=${TOKENIZER_PATH} dataset_type=grain grain_file_type=tfrecord dataset_path=${DATASET_PATH} enable_checkpointing=false attention=dot_product dtype=bfloat16 weight_dtype=bfloat16 per_device_batch_size=1 steps=5 max_target_length=256 remat_policy=full ici_fsdp_parallelism=-1 ici_tensor_parallelism=4 opt_type=sgd

# Run fine-tuning
# Checkpointing stays enabled for the restore; saves are disabled because each checkpoint is ~1.6 TB.
python3 -m maxtext.trainers.pre_train.train ${MAXTEXT_CONFIGS_DIR:-${MAXTEXT_REPO_ROOT:-$PWD}/src/maxtext/configs}/base.yml base_output_directory=${BASE_OUTPUT_PATH} run_name=muse_spark_fine_tuning model_name=${MODEL_NAME} tokenizer_type=huggingface tokenizer_path=${TOKENIZER_PATH} dataset_type=grain grain_file_type=tfrecord dataset_path=${DATASET_PATH} enable_checkpointing=true async_checkpointing=false save_checkpoint_on_start=false save_checkpoint_on_completion=false load_parameters_path=${SCANNED_CKPT_PATH} scan_layers=true attention=dot_product dtype=bfloat16 weight_dtype=bfloat16 per_device_batch_size=1 steps=5 max_target_length=256 remat_policy=full ici_fsdp_parallelism=-1 ici_tensor_parallelism=4 opt_type=sgd

# Run decoding
# Note decode requires the access token for huggingface tokenizer even if the model is not gated
python3 -m maxtext.inference.decode ${MAXTEXT_CONFIGS_DIR:-${MAXTEXT_REPO_ROOT:-$PWD}/src/maxtext/configs}/base.yml base_output_directory=${BASE_OUTPUT_PATH} run_name=decode model_name=${MODEL_NAME} tokenizer_type=huggingface tokenizer_path=${TOKENIZER_PATH} hf_access_token=${HF_TOKEN} load_parameters_path=${UNSCANNED_CKPT_PATH} scan_layers=false attention=dot_product dtype=bfloat16 weight_dtype=bfloat16 per_device_batch_size=0.25 max_prefill_predict_length=64 max_target_length=128 ici_fsdp_parallelism=-1 ici_tensor_parallelism=4 decode_sampling_strategy=greedy prompt="An attention function can be described as mapping a query and a set of key-value pairs to an output, where the query, keys, values, and outputs are all vectors. The output is "
